style.css:
@-moz-document domain("roblox.com") {
/* Hide advertisements */
  .ad, .ad *, .img_ad, .ad-annotations, #google_image_div, #aw0, #AdvertisingLeaderboard,
  #Skyscraper-Abp-Left, #Skyscraper-Abp-Right {
    visibility: hidden !important;
  } /* Ad removal fixed even further by DittoDino/BoopBop */

  /* Header & Navigation */
  #header {
    background-color: #000000 !important;
  }

  .navigation .notification-icon,
  .rbx-highlight {
    background: #000000 !important;
  }

  /* Chat Header */
  #chat-header {
    background: #000000 !important;
  }

  /* Left containers */
  .slide-item-container-left,
  .profile-avatar-right {
    background: #000000 !important;
  }

  /* Tabs */
  .rbx-tabs-horizontal .rbx-tab.active .rbx-tab-heading,
  .rbx-tabs-horizontal .rbx-tab-heading:hover,
  .rbx-tabs-horizontal .rbx-tab-heading:focus,
  .rbx-tabs-horizontal .rbx-tab-heading:active {
    box-shadow: 0 -4px 0 #000000 inset !important;
  }

  /* Forum headers */
  .forum-table-header,
  body .forum-table-header th,
  body .forum-table-footer,
  #ctl00_cphRoblox_Message1_ctl00_CenterColumn > table > tbody > tr:nth-child(1) > th,
  #ctl00_cphRoblox_CenterColumn > table > tbody > tr:nth-child(1) > th {
    background: #000000 !important;
  }

  /* Upgrade/Buttons */
  .rbx-upgrade-now #upgrade-now-button,
  .rbx-btn-secondary-xs.btn-more,
  #AjaxCommentsContainer > div > div.comment-form > form > button,
  .rbx-vip-server-create,
  .btn-secondary-xs {
    background-color: #000000 !important;
    border-color: #000000 !important;
  }

  .rbx-upgrade-now #upgrade-now-button:hover,
  .rbx-btn-secondary-xs.btn-more:hover,
  #AjaxCommentsContainer > div > div.comment-form > form > button:hover,
  .rbx-vip-server-create:hover,
  .btn-secondary-xs:hover {
    background: #000000 !important;
    border-color: #000000 !important;
  }

  /* (Optional) Hide right-side columns.
     This rule was originally intended for profile pages.
     If you want the theme to work everywhere (Home, Avatar, Inventory, etc.),
     you might want to leave these commented out. */
  /*
  #ctl00_cphRoblox_RightColumn,
  #Body > table > tbody > tr > td:nth-child(3),
  #Body > table > tbody > tr > td:nth-child(4) {
    display: none !important;
  }
  */

  /* Hide other ad/spacer containers */
  #TopAbpContainer,
  .ad-annotations,
  #LeftGutterAdContainer,
  #RightGutterAdContainer,
  #Skyscraper-Adp-Right,
  #Skyscraper-Adp-Left,
  .abp-spacer,
  #GamesListContainer1 > div.games-list > ul > div.abp.in-game-search-ad.dynamic-ad.ad-order-even,
  #GamesListContainer1 > div.games-list > ul > div.abp.in-game-search-ad.dynamic-ad.ad-order-odd,
  #GamesListContainer8 > div.games-list > ul > div.abp.in-game-search-ad.dynamic-ad.ad-order-even,
  #GamesListContainer8 > div.games-list > ul > div.abp.in-game-search-ad.dynamic-ad.ad-order-odd,
  .sponsored-game,
  .alert-info,
  #mCSB_1_container > ul > li.font-bold.small,
  #mCSB_1_container > ul > li.rbx-nav-sponsor {
    display: none !important;
  }

  /* Navbar search */
  #navbar-search-input,
  #navbar-search-btn {
    border: 1px solid #000000 !important;
  }

  /* Global Background & Layout */
  html, body {
    width: 100% !important;
    height: 100% !important;
    background-color: #000000 !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-image: url("https://ibb.co/SXyRzS0k") !important;
    /* If the above URL doesn’t display your image, replace it with a direct image link (ending in .png/.jpg/etc.). */
  }

  .content {
    background: transparent !important;
  }

  .container-footer {
    position: static !important;
  }

  /* Party header and chat tweaks */
  #party_none_title,
  div.friend_dock_chatbox_titlebar.chat-header-blink-off {
    background: linear-gradient(to bottom, #000000, #000000) !important;
  }

  /* Games page layout */
  #GamesPageLeftColumn {
    width: auto !important;
    margin-right: 10px !important;
    margin-left: 10px !important;
  }

  #GamesListsContainer > div {
    background-color: transparent !important;
    width: 100% !important;
  }

  /* Navigation bar tweak */
  #navigation {
    background-color: rgba(12, 12, 12, 0.8) !important;
  }

  /* Primary buttons */
  .rbx-btn-primary-lg {
    background-color: rgba(255, 255, 255, 0.5) !important;
  }

  .rbx-btn-primary-lg:hover,
  .rbx-btn-primary-lg:focus {
    background-color: rgba(255, 255, 255, 0.5) !important;
  }

  /* Dark theme tweaks for friends list and avatars */
  .dark-theme .people-list .friend .friend-link {
    color: #fff !important;
  }

  .dark-theme .avatar-container .avatar-card-image,
  .dark-theme .avatar-container img {
    background-color: #0c0c0c !important;
  }

  /* Ensure our background is always underneath other content */
  body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: inherit;
    z-index: -1;
  }
}
